using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// Exercises the real HttpClient pipeline against a stubbed transport, proving the
/// wire contract with the provider: what we POST to /v1/authorizations and how we
/// interpret every answer it can give back, including its outright refusal (402).
/// </summary>
public sealed class HttpPaymentGatewayTests
{
    [Fact]
    public async Task Sends_the_reference_amount_and_currency_as_the_provider_expects()
    {
        var transport = new StubHttpMessageHandler(_ => JsonResponse(HttpStatusCode.OK, """{"status":"approved"}"""));
        var sut = new HttpPaymentGateway(CreateClient(transport));

        await sut.AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        Assert.NotNull(transport.LastRequest);
        Assert.Equal(HttpMethod.Post, transport.LastRequest!.Method);
        Assert.Equal("/v1/authorizations", transport.LastRequest.RequestUri!.AbsolutePath);

        using var body = JsonDocument.Parse(transport.LastRequestBody!);
        Assert.Equal("ORD-7", body.RootElement.GetProperty("reference").GetString());
        Assert.Equal(12.50m, body.RootElement.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", body.RootElement.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_response_is_read_back_as_Approved()
    {
        var transport = new StubHttpMessageHandler(_ => JsonResponse(HttpStatusCode.OK, """{"status":"approved"}"""));
        var sut = new HttpPaymentGateway(CreateClient(transport));

        var outcome = await sut.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_response_is_read_back_as_Declined()
    {
        var transport = new StubHttpMessageHandler(_ => JsonResponse(HttpStatusCode.OK, """{"status":"declined"}"""));
        var sut = new HttpPaymentGateway(CreateClient(transport));

        var outcome = await sut.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unknown_status_value_is_treated_as_Declined()
    {
        var transport = new StubHttpMessageHandler(_ => JsonResponse(HttpStatusCode.OK, """{"status":"pending"}"""));
        var sut = new HttpPaymentGateway(CreateClient(transport));

        var outcome = await sut.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task The_provider_refusing_outright_with_402_is_read_back_as_Declined()
    {
        var transport = new StubHttpMessageHandler(_ => new HttpResponseMessage(HttpStatusCode.PaymentRequired));
        var sut = new HttpPaymentGateway(CreateClient(transport));

        var outcome = await sut.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_provider_error_bubbles_up_instead_of_being_swallowed()
    {
        var transport = new StubHttpMessageHandler(_ => new HttpResponseMessage(HttpStatusCode.InternalServerError));
        var sut = new HttpPaymentGateway(CreateClient(transport));

        await Assert.ThrowsAsync<HttpRequestException>(
            () => sut.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None));
    }

    private static HttpClient CreateClient(HttpMessageHandler handler)
        => new(handler) { BaseAddress = new Uri("https://provider.example.test") };

    private static HttpResponseMessage JsonResponse(HttpStatusCode status, string json)
        => new(status) { Content = new StringContent(json, Encoding.UTF8, "application/json") };

    /// <summary>A fake transport standing in for the provider's REST endpoint, capturing what we sent it.</summary>
    private sealed class StubHttpMessageHandler(Func<HttpRequestMessage, HttpResponseMessage> respond) : HttpMessageHandler
    {
        public HttpRequestMessage? LastRequest { get; private set; }
        public string? LastRequestBody { get; private set; }

        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
        {
            LastRequest = request;
            LastRequestBody = request.Content is null ? null : await request.Content.ReadAsStringAsync(cancellationToken);
            return respond(request);
        }
    }
}

